    Write-Warning "Package download attempt $attempt failed: $_"
    Start-Sleep -Seconds 10
  }
}
$hash = [Convert]::ToBase64String([Security.Cryptography.SHA512]::HashData([IO.File]::ReadAllBytes($package)))
