Expand-Archive $package -DestinationPath $target -Force
Remove-Item -Recurse -Force (Join-Path $target '_rels'), (Join-Path $target 'package') -ErrorAction SilentlyContinue
Remove-Item -Force -LiteralPath (Join-Path $target '[Content_Types].xml') -ErrorAction SilentlyContinue
Remove-Item -Force -Path (Join-Path $target '*.nuspec') -ErrorAction SilentlyContinue
